1	/**
2	 * Split Payment routes
3	 *
4	 * POST /api/games/checkout-split  — host initiates a split booking + game + pays their share
5	 * GET  /api/bookings/share/:token — public: get split booking info (for invite page)
6	 * POST /api/bookings/share/:token/checkout — invitee pays their share
7	 * GET  /api/bookings/:bookingId/split-status — host/participant: see all payment statuses
8	 */
9	import { Router, type IRouter } from "express";
10	import { and, eq, ne, sql } from "drizzle-orm";
11	import {
12	  db,
13	  bookingsTable,
14	  courtsTable,
15	  facilitiesTable,
16	  gamesTable,
17	  gameParticipantsTable,
18	  userProfilesTable,
19	  userSportProfilesTable,
20	  courtBlockedSlotsTable,
21	} from "@workspace/db";
22	import { buildDayPriceMap } from "../lib/pricing";
23	
24	import { requireAuth, getCurrentUserId } from "../lib/auth";
25	import { getAuth } from "@clerk/express";
26	import { getUncachableStripeClient } from "../stripeClient";
27	import { logger } from "../lib/logger";
28	import { sendSplitBookingCreatedEmail, sendSplitPlayerJoinedEmail, sendSplitParticipantConfirmationEmail } from "../lib/email";
29	import { sendNotification } from "../lib/notify";
30	import { z } from "zod";
31	import crypto from "node:crypto";
32	
33	const router: IRouter = Router();
34	
35	// ─── Helpers ─────────────────────────────────────────────────────────────────
36	
37	function toMin(t: string): number {
38	  const [h, m] = t.split(":").map(Number);
39	  return h * 60 + m;
40	}
41	
42	function slotsBetween(startTime: string, endTime: string): string[] {
43	  const slots: string[] = [];
44	  let cur = toMin(startTime);
45	  const end = toMin(endTime);
46	  while (cur < end) {
47	    const h = Math.floor(cur / 60).toString().padStart(2, "0");
48	    const m = (cur % 60).toString().padStart(2, "0");
49	    slots.push(`${h}:${m}`);
50	    cur += 30;
51	  }
52	  return slots;
53	}
54	
55	// ─── POST /api/games/checkout-split ──────────────────────────────────────────
56	
57	const SplitCheckoutBody = z.object({
58	  courtId: z.number().int().positive(),
59	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
60	  startTime: z.string().regex(/^\d{2}:\d{2}$/),
61	  endTime: z.string().regex(/^\d{2}:\d{2}$/),
62	  totalSlots: z.number().int().min(2).max(8),
63	  sport: z.string().min(1),
64	  skillLevel: z.string().optional().default("any"),
65	  description: z.string().optional(),
66	  customerName: z.string().min(1),
67	  customerEmail: z.string().email(),
68	  customerPhone: z.string().optional(),
69	  // Open match fields
70	  isPublic: z.boolean().optional().default(false),
71	  minSkillLevel: z.number().min(0).max(10).optional(),
72	  maxSkillLevel: z.number().min(0).max(10).optional(),
73	  matchType: z.enum(["casual", "competitive"]).optional().default("casual"),
74	  // Upgrade flow: link an existing casual game instead of creating a new one
75	  linkGameId: z.number().int().positive().optional(),
76	});
77	
78	router.post("/games/checkout-split", requireAuth, async (req, res): Promise<void> => {
79	  const userId = getCurrentUserId(req)!;
80	  const parsed = SplitCheckoutBody.safeParse(req.body);
81	  if (!parsed.success) {
82	    res.status(400).json({ error: parsed.error.message });
83	    return;
84	  }
85	
86	  const {
87	    courtId, date, startTime, endTime, totalSlots, sport, skillLevel, description,
88	    customerName, customerEmail, customerPhone,
89	    isPublic, minSkillLevel, maxSkillLevel, matchType,
90	    linkGameId,
91	  } = parsed.data;
92	
93	  const reqStartMin = toMin(startTime);
94	  const reqEndMin = toMin(endTime);
95	  if (reqEndMin <= reqStartMin) {
96	    res.status(400).json({ error: "endTime must be after startTime" });
97	    return;
98	  }
99	
100	  // ── Fetch court and facility ──────────────────────────────────────────────
101	  const [courtRow] = await db
102	    .select({ court: courtsTable, facility: facilitiesTable })
103	    .from(courtsTable)
104	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
105	    .where(eq(courtsTable.id, courtId));
106	
107	  if (!courtRow?.court) {
108	    res.status(404).json({ error: "Court not found" });
109	    return;
110	  }
111	
112	  const { court, facility } = courtRow;
113	
114	  // ── Server-side price calculation ─────────────────────────────────────────
115	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
116	  const { priceMap } = await buildDayPriceMap(courtId, date, defaultSlotPrice);
117	
118	  const slots = slotsBetween(startTime, endTime);
119	  let courtPrice = 0;
120	  for (const slotStart of slots) {
121	    courtPrice += priceMap.get(slotStart) ?? defaultSlotPrice;
122	  }
123	
124	  const totalPrice = courtPrice;
125	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
126	  const durationMinutes = reqEndMin - reqStartMin;
127	
128	  // ── Conflict check ────────────────────────────────────────────────────────
129	  const conflictingBookings = await db
130	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
131	    .from(bookingsTable)
132	    .where(and(
133	      eq(bookingsTable.courtId, courtId),
134	      eq(bookingsTable.date, date),
135	      sql`${bookingsTable.status} IN ('confirmed', 'blocked', 'awaiting_players')`,
136	    ));
137	
138	  const recentPending = await db
139	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
140	    .from(bookingsTable)
141	    .where(and(
142	      eq(bookingsTable.courtId, courtId),
143	      eq(bookingsTable.date, date),
144	      eq(bookingsTable.status, "pending"),
145	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
146	    ));
147	
148	  const allConflicting = [...conflictingBookings, ...recentPending];
149	  for (const b of allConflicting) {
150	    const bStart = toMin(b.startTime);
151	    const bEnd = toMin(b.endTime);
152	    if (reqStartMin < bEnd && reqEndMin > bStart) {
153	      res.status(409).json({ error: "Pasirinktas laikas užimtas", code: "SLOT_UNAVAILABLE" });
154	      return;
155	    }
156	  }
157	
158	  // Also check blocked slots
159	  const blockedSlots = await db
160	    .select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
161	    .from(courtBlockedSlotsTable)
162	    .where(and(
163	      eq(courtBlockedSlotsTable.courtId, courtId),
164	      eq(courtBlockedSlotsTable.date, date),
165	    ));
166	
167	  for (const b of blockedSlots) {
168	    const bStart = toMin(b.startTime);
169	    const bEnd = toMin(b.endTime);
170	    if (reqStartMin < bEnd && reqEndMin > bStart) {
171	      res.status(409).json({ error: "Pasirinktas laikas užblokuotas", code: "SLOT_BLOCKED" });
172	      return;
173	    }
174	  }
175	
176	  // ── Create booking ────────────────────────────────────────────────────────
177	  const splitInviteToken = crypto.randomBytes(20).toString("hex");
178	  const datetime = `${date}T${startTime}:00`;
179	
180	  const [booking] = await db.insert(bookingsTable).values({
181	    courtId,
182	    bookerUserId: userId,
183	    customerName,
184	    customerEmail,
185	    customerPhone: customerPhone ?? null,
186	    date,
187	    startTime,
188	    endTime,
189	    totalPrice: String(totalPrice),
190	    status: "pending",
191	    isSplit: true,
192	    totalSlots,
193	    pricePerSlot: String(pricePerSlot),
194	    splitInviteToken,
195	  }).returning();
196	
197	  // ── Create or reuse linked game ───────────────────────────────────────────
198	  let gameId: number;
199	  if (linkGameId) {
200	    // Upgrade flow: verify the caller owns the game before linking it.
201	    const [targetGame] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
202	    if (!targetGame) {
203	      res.status(404).json({ error: "Linked game not found" });
204	      return;
205	    }
206	    if (targetGame.creatorUserId !== userId) {
207	      res.status(403).json({ error: "Forbidden" });
208	      return;
209	    }
210	    gameId = linkGameId;
211	  } else {
212	    const [newGame] = await db.insert(gamesTable).values({
213	      creatorUserId: userId,
214	      creatorName: customerName,
215	      creatorEmail: customerEmail,
216	      sport,
217	      city: facility?.city ?? "",
218	      placeName: facility?.name ?? court.name,
219	      facilityId: facility?.id ?? null,
220	      courtId,
221	      bookingId: booking.id,
222	      playersNeeded: totalSlots,
223	      skillLevel: skillLevel ?? "any",
224	      datetime,
225	      durationMinutes,
226	      description: description ?? null,
227	      status: "pending_payment",
228	      matchType: matchType ?? "casual",
229	      isPrivate: !isPublic,
230	      visibility: isPublic ? "public" : "private",
231	      minSkillLevel: isPublic ? (minSkillLevel ?? null) : null,
232	      maxSkillLevel: isPublic ? (maxSkillLevel ?? null) : null,
233	      requiresApproval: false,
234	      teamCount: 2,
235	    }).returning();
236	    gameId = newGame.id;
237	  }
238	
239	  // ── Add host as participant (pending payment) ─────────────────────────────
240	  // For the upgrade flow, update the existing host participant to track payment;
241	  // for the normal flow, insert a fresh record.
242	  let hostParticipant: typeof gameParticipantsTable.$inferSelect;
243	  if (linkGameId) {
244	    const [existing] = await db
245	      .select()
246	      .from(gameParticipantsTable)
247	      .where(and(eq(gameParticipantsTable.gameId, linkGameId), eq(gameParticipantsTable.userId, userId)));
248	    if (existing) {
249	      [hostParticipant] = await db
250	        .update(gameParticipantsTable)
251	        .set({ paymentStatus: "pending" })
252	        .where(eq(gameParticipantsTable.id, existing.id))
253	        .returning();
254	    } else {
255	      [hostParticipant] = await db.insert(gameParticipantsTable).values({
256	        gameId: linkGameId,
257	        userId,
258	        userName: customerName,
259	        userEmail: customerEmail,
260	        status: "joined",
261	        source: "join_request",
262	        paymentStatus: "pending",
263	      }).returning();
264	    }
265	  } else {
266	    [hostParticipant] = await db.insert(gameParticipantsTable).values({
267	      gameId,
268	      userId,
269	      userName: customerName,
270	      userEmail: customerEmail,
271	      status: "joined",
272	      source: "join_request",
273	      paymentStatus: "pending",
274	    }).returning();
275	  }
276	
277	  // ── Create Stripe checkout for host's share ───────────────────────────────
278	  const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
279	  const base = process.env.BASE_PATH ?? "";
280	  const successUrl = `${origin}${base}/booking-confirmed?id=${booking.id}&split=1`;
281	  const cancelUrl = `${origin}${base}/courts/${courtId}?booking_cancelled=1&bookingId=${booking.id}`;
282	
283	  let checkoutUrl: string;
284	
285	  try {
286	    const stripe = await getUncachableStripeClient();
287	
288	    // Resolve Connect account
289	    let connectAccountId: string | null = null;
290	    if (facility?.ownerUserId) {
291	      const [profile] = await db
292	        .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
293	        .from(userProfilesTable)
294	        .where(eq(userProfilesTable.userId, facility.ownerUserId));
295	      if (profile?.stripeAccountId && profile.status === "active") {
296	        connectAccountId = profile.stripeAccountId;
297	      }
298	    }
299	
300	    const amountCents = Math.round(pricePerSlot * 100);
301	    const sessionParams: any = {
302	      payment_method_types: ["card"],
303	      line_items: [{
304	        price_data: {
305	          currency: "eur",
306	          product_data: {
307	            name: `${court.name} – mokėjimo dalis (1/${totalSlots})`,
308	            description: `${date} · ${startTime}–${endTime}`,
309	          },
310	          unit_amount: amountCents,
311	        },
312	        quantity: 1,
313	      }],
314	      mode: "payment",
315	      success_url: `${successUrl}&session_id={CHECKOUT_SESSION_ID}`,
316	      cancel_url: cancelUrl,
317	      metadata: {
318	        bookingId: String(booking.id),
319	        splitParticipantId: String(hostParticipant.id),
320	        ...(linkGameId ? { linkGameId: String(linkGameId) } : {}),
321	      },
322	      customer_email: customerEmail,
323	      locale: "lt",
324	    };
325	
326	    if (connectAccountId) {
327	      const feeAmount = Math.round(amountCents * 5 / 100);
328	      sessionParams.payment_intent_data = {
329	        application_fee_amount: feeAmount,
330	        transfer_data: { destination: connectAccountId },
331	      };
332	    }
333	
334	    const session = await stripe.checkout.sessions.create(sessionParams);
335	
336	    // Store session ids
337	    await db.update(bookingsTable)
338	      .set({ stripeSessionId: session.id })
339	      .where(eq(bookingsTable.id, booking.id));
340	
341	    await db.update(gameParticipantsTable)
342	      .set({ stripeSessionId: session.id })
343	      .where(eq(gameParticipantsTable.id, hostParticipant.id));
344	
345	    checkoutUrl = session.url!;
346	
347	  } catch (err: any) {
348	    if (err?.message?.includes("Stripe not configured") || err?.type === "StripeAuthenticationError") {
349	      // Mock checkout for dev
350	      const mockId = `mock_split_${booking.id}_${Date.now()}`;
351	      await db.update(bookingsTable)
352	        .set({ stripeSessionId: mockId, status: "awaiting_players" })
353	        .where(eq(bookingsTable.id, booking.id));
354	      await db.update(gameParticipantsTable)
355	        .set({ stripeSessionId: mockId, paymentStatus: "paid" })
356	        .where(eq(gameParticipantsTable.id, hostParticipant.id));
357	      if (linkGameId) {
358	        await db.update(gamesTable)
359	          .set({
360	            bookingId: booking.id,
361	            facilityId: facility?.id ?? null,
362	            courtId,
363	            status: "awaiting_players",
364	            datetime: `${booking.date}T${booking.startTime}:00`,
365	            durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
366	          })
367	          .where(eq(gamesTable.id, linkGameId));
368	      } else {
369	        await db.update(gamesTable)
370	          .set({ status: "awaiting_players" })
371	          .where(eq(gamesTable.id, gameId));
372	      }
373	      checkoutUrl = `${successUrl}&session_id=${mockId}`;
374	    } else {
375	      logger.error({ err }, "Failed to create Stripe session for split checkout");
376	      if (!linkGameId) {
377	        // Rollback only applies when we created a new game
378	        await db.update(bookingsTable).set({ status: "cancelled" }).where(eq(bookingsTable.id, booking.id));
379	        await db.delete(gamesTable).where(eq(gamesTable.id, gameId));
380	      }
381	      res.status(500).json({ error: "Failed to create payment session" });
382	      return;
383	    }
384	  }
385	
386	  res.status(201).json({
387	    url: checkoutUrl,
388	    bookingId: booking.id,
389	    gameId,
390	    shareToken: splitInviteToken,
391	    pricePerSlot,
392	    totalPrice,
393	    totalSlots,
394	  });
395	});
396	
397	// ─── POST /api/payments/confirm-split ────────────────────────────────────────
398	// Called by booking-confirmed.tsx when ?split=1 is present.
399	// Marks the host participant as paid, moves booking→awaiting_players, game→awaiting_players.
400	
401	router.post("/payments/confirm-split", requireAuth, async (req, res): Promise<void> => {
402	  const userId = getCurrentUserId(req)!;
403	  const sessionId = String(req.body?.sessionId ?? "");
404	  if (!sessionId) { res.status(400).json({ error: "sessionId required" }); return; }
405	
406	  // Find the booking (and court) by stripeSessionId
407	  const rows = await db
408	    .select({ booking: bookingsTable, court: courtsTable })
409	    .from(bookingsTable)
410	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
411	    .where(eq(bookingsTable.stripeSessionId, sessionId));
412	
413	  if (!rows[0]) { res.status(404).json({ error: "Booking not found for session" }); return; }
414	  const { booking, court } = rows[0];
415	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
416	  if (booking.bookerUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
417	
418	  // Verify Stripe payment and read metadata (skip for mocks)
419	  let linkGameId: number | null = null;
420	  if (!sessionId.startsWith("mock_")) {
421	    try {
422	      const stripe = await getUncachableStripeClient();
423	      const session = await stripe.checkout.sessions.retrieve(sessionId);
424	      if (session.payment_status !== "paid") {
425	        res.status(402).json({ error: "Payment not completed" });
426	        return;
427	      }
428	      const lgId = session.metadata?.linkGameId;
429	      if (lgId) linkGameId = parseInt(lgId, 10);
430	    } catch (err) {
431	      logger.error({ err }, "Stripe retrieve session error in confirm-split");
432	    }
433	  }
434	
435	  // Find participant by stripeSessionId → mark as paid (idempotent)
436	  const [participant] = await db
437	    .select()
438	    .from(gameParticipantsTable)
439	    .where(eq(gameParticipantsTable.stripeSessionId, sessionId));
440	
441	  if (participant && participant.paymentStatus !== "paid") {
442	    await db
443	      .update(gameParticipantsTable)
444	      .set({ paymentStatus: "paid" })
445	      .where(eq(gameParticipantsTable.id, participant.id));
446	  }
447	
448	  // Move booking to awaiting_players (from pending) — track if this is a fresh transition
449	  let justTransitioned = false;
450	  if (booking.status === "pending") {
451	    const updated = await db
452	      .update(bookingsTable)
453	      .set({ status: "awaiting_players" })
454	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")))
455	      .returning();
456	    justTransitioned = updated.length > 0;
457	  }
458	
459	  // Find linked game and transition it
460	  let game: typeof gamesTable.$inferSelect | undefined;
461	  if (linkGameId) {
462	    // Upgrade flow: update the pre-existing casual game
463	    const [courtRow] = await db
464	      .select({ facilityId: facilitiesTable.id, courtId: courtsTable.id })
465	      .from(courtsTable)
466	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
467	      .where(eq(courtsTable.id, booking.courtId));
468	    await db
469	      .update(gamesTable)
470	      .set({
471	        bookingId: booking.id,
472	        facilityId: courtRow?.facilityId ?? null,
473	        courtId: courtRow?.courtId ?? booking.courtId,
474	        status: "awaiting_players",
475	        datetime: `${booking.date}T${booking.startTime}:00`,
476	        durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
477	      })
478	      .where(eq(gamesTable.id, linkGameId));
479	    const [updated] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
480	    game = updated;
481	  } else {
482	    // Normal flow: find the game that was created alongside this booking
483	    const [found] = await db
484	      .select()
485	      .from(gamesTable)
486	      .where(eq(gamesTable.bookingId, booking.id));
487	    if (found && found.status === "pending_payment") {
488	      await db
489	        .update(gamesTable)
490	        .set({ status: "awaiting_players" })
491	        .where(and(eq(gamesTable.id, found.id), eq(gamesTable.status, "pending_payment")));
492	    }
493	    game = found;
494	  }
495	
496	  // Aggregate paid participant count
497	  const allParticipants = game
498	    ? await db
499	        .select({ paymentStatus: gameParticipantsTable.paymentStatus })
500	        .from(gameParticipantsTable)
501	        .where(and(
502	          eq(gameParticipantsTable.gameId, game.id),
503	          eq(gameParticipantsTable.status, "joined"),
504	        ))
505	    : [];
506	  const paidSlots = allParticipants.filter(p => p.paymentStatus === "paid").length;
507	
508	  // Send email + notification to host if this was a fresh game creation
509	  if (justTransitioned && booking.bookerUserId && booking.splitInviteToken) {
510	    const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
511	    const base = process.env.BASE_PATH ?? "";
512	    const shareLink = `${origin}${base}/join/${booking.splitInviteToken}`;
513	
514	    sendSplitBookingCreatedEmail({
515	      hostName: booking.customerName,
516	      hostEmail: booking.customerEmail,
517	      courtName: court?.name ?? "Kortas",
518	      courtId: booking.courtId,
519	      date: booking.date,
520	      startTime: booking.startTime,
521	      endTime: booking.endTime,
522	      pricePerSlot: Number(booking.pricePerSlot ?? 0),
523	      totalPrice: Number(booking.totalPrice),
524	      totalSlots: booking.totalSlots ?? 1,
525	      shareLink,
526	      bookingId: booking.id,
527	    }).catch((err) => logger.error({ err }, "sendSplitBookingCreatedEmail failed"));
528	
529	    sendNotification(
530	      booking.bookerUserId,
531	      "split_player_joined",
532	      "Žaidimas sukurtas!",
533	      `Jūsų vieta aikštelėje ${court?.name ?? "kortas"} (${booking.date}) patvirtinta. Dalinkitės nuoroda su žaidėjais.`,
534	      `/bookings/${booking.id}`,
535	    ).catch(() => {});
536	  }
537	
538	  res.json({
539	    bookingId: booking.id,
540	    gameId: game?.id ?? null,
541	    shareToken: booking.splitInviteToken ?? null,
542	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
543	    totalSlots: booking.totalSlots ?? 1,
544	    paidSlots,
545	    totalPrice: Number(booking.totalPrice),
546	    date: booking.date,
547	    startTime: booking.startTime,
548	    endTime: booking.endTime,
549	    sport: game?.sport ?? null,
550	    isPublic: game?.visibility === "public",
551	    courtId: booking.courtId,
552	    courtName: court?.name ?? null,
553	    courtImageUrl: court?.imageUrl ?? null,
554	  });
555	});
556	
557	// ─── GET /api/bookings/share/:token ──────────────────────────────────────────
558	
559	router.get("/bookings/share/:token", async (req, res): Promise<void> => {
560	  const token = String(req.params.token);
561	  if (!token) { res.status(400).json({ error: "Token required" }); return; }
562	
563	  const rows = await db
564	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
565	    .from(bookingsTable)
566	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
567	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
568	    .where(eq(bookingsTable.splitInviteToken, token));
569	
