47	// Booking `date`/`startTime` are stored as Lithuanian local time strings. The
48	// server runs in UTC, so naively parsing `${date}T${startTime}:00` would treat
49	// them as UTC and give a result that is wrong by Vilnius's DST offset (2–3h).
50	// Compute the UTC instant for the Vilnius wall-clock time, then diff against
51	// `Date.now()` in absolute milliseconds.
52	export function vilniusLocalToUtcMs(date: string, time: string): number {
53	  const dateOnly = String(date).slice(0, 10);
54	  // Step 1: pretend the local string is UTC.
55	  const naiveUtcMs = Date.parse(`${dateOnly}T${time}:00Z`);
56	  // Step 2: ask what Europe/Vilnius wall-clock that UTC instant displays.
57	  const fmt = new Intl.DateTimeFormat("en-GB", {
58	    timeZone: "Europe/Vilnius",
59	    year: "numeric", month: "2-digit", day: "2-digit",
60	    hour: "2-digit", minute: "2-digit", second: "2-digit",
61	    hour12: false,
62	  });
63	  const parts = fmt.formatToParts(new Date(naiveUtcMs));
64	  const get = (t: string) => parts.find(p => p.type === t)!.value;
65	  let hh = get("hour");
66	  if (hh === "24") hh = "00";
67	  const vilniusAsUtcMs = Date.UTC(
68	    Number(get("year")), Number(get("month")) - 1, Number(get("day")),
69	    Number(hh), Number(get("minute")), Number(get("second")),
70	  );
71	  // Offset = how many ms Vilnius is AHEAD of UTC at that instant (+2h or +3h).
72	  const offsetMs = vilniusAsUtcMs - naiveUtcMs;
73	  // Subtract offset to get the actual UTC instant for that Vilnius wall-clock time.
74	  return naiveUtcMs - offsetMs;
75	}
