40	function toMin(t: string): number {
41	  const [h, m] = t.split(":").map(Number);
42	  return h * 60 + m;
43	}
44	function slotsBetween(startTime: string, endTime: string): string[] {
45	  const start = toMin(startTime);
46	  const end = toMin(endTime);
47	  const out: string[] = [];
48	  for (let m = start; m < end; m += 30) {
49	    const h = String(Math.floor(m / 60)).padStart(2, "0");
50	    const mm = String(m % 60).padStart(2, "0");
51	    out.push(`${h}:${mm}`);
52	  }
53	  return out;
54	}
