37	export async function handleStripeWebhook(req: Request, res: Response): Promise<void> {
38	  const sigHeader = req.headers["stripe-signature"];
39	  if (!sigHeader) {
40	    res.status(400).json({ error: "Missing stripe-signature header" });
41	    return;
42	  }
43	  const signature = Array.isArray(sigHeader) ? sigHeader[0] : sigHeader;
44	
45	  let stripe: Stripe;
46	  let webhookSecret: string;
47	  try {
48	    stripe = getStripe();
49	    webhookSecret = getStripeWebhookSecret();
50	  } catch (err: any) {
51	    logger.error({ err }, "Stripe not configured for webhook");
52	    res.status(503).json({ error: "Stripe not configured" });
53	    return;
54	  }
55	
56	  if (!Buffer.isBuffer(req.body)) {
57	    logger.error(
58	      "Stripe webhook body is not a Buffer — express.json() must run AFTER this route",
59	    );
60	    res.status(400).json({ error: "Invalid body" });
61	    return;
62	  }
63	
64	  let event: Stripe.Event;
65	  try {
66	    event = stripe.webhooks.constructEvent(req.body, signature, webhookSecret);
67	  } catch (err: any) {
68	    logger.warn({ err: err?.message }, "Stripe webhook signature verification failed");
69	    res.status(400).json({ error: `Webhook Error: ${err?.message}` });
70	    return;
71	  }
72	
73	  try {
74	    switch (event.type) {
75	      case "checkout.session.completed":
76	      case "checkout.session.async_payment_succeeded": {
77	        const session = event.data.object as Stripe.Checkout.Session;
78	        await handleCheckoutCompleted(session);
79	        break;
80	      }
81	      case "checkout.session.expired": {
82	        const session = event.data.object as Stripe.Checkout.Session;
83	        await handleCheckoutExpired(session);
84	        break;
85	      }
86	      case "account.updated": {
87	        const account = event.data.object as Stripe.Account;
88	        await handleAccountUpdated(account);
89	        break;
90	      }
91	      default:
92	        logger.debug({ type: event.type }, "Stripe webhook received (unhandled)");
93	    }
94	  } catch (err) {
95	    logger.error({ err, type: event.type }, "Stripe webhook handler failed");
96	    // Still return 200 so Stripe doesn't retry indefinitely on our app errors;
97	    // bookings are already protected by /api/payments/confirm fallback.
98	  }
99	
100	  res.status(200).json({ received: true });

100	  res.status(200).json({ received: true });
101	}
